import assert from 'node:assert/strict';import test from 'node:test';import {readFileSync} from 'node:fs';
import {verifyMobileChoiceVisibilityRelease} from './check-mobile-choice-visibility-release-20261101.mjs';
void test('The exact approved mobile-only repair retains all old source and release evidence',()=>assert.equal(verifyMobileChoiceVisibilityRelease().approvedBy,'Nico'));
for(const [file,mutate]of [['docs/klink-owner-release-mobile-choice-visibility-20261101.json',r=>{r.publicationApproved=false;}],['docs/mobile-choice-visibility-20261101/local/checks.json',r=>{r.checks.pop();}],['docs/mobile-choice-visibility-20261101/backup.json',r=>{r.fullReadback=false;}]])void test('Reject missing permission/proof: '+file,()=>assert.throws(()=>verifyMobileChoiceVisibilityRelease(f=>{const b=readFileSync(f);if(f!==file)return b;const r=JSON.parse(b);mutate(r);return Buffer.from(JSON.stringify(r));})));
void test('Reject changes outside the exact approved CSS',()=>assert.throws(()=>verifyMobileChoiceVisibilityRelease(f=>f==='app/learner-layout.css'?Buffer.from(readFileSync(f).toString()+'\nbody{display:none}'):readFileSync(f))));
